import { useState } from "react";
import { motion } from "framer-motion";
import logo from "./assets/logo.png";

const PAYMENT_LINK = "https://your-payment-link.com";

function App() {
  const [text, setText] = useState("");
  const [cvText, setCvText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleExtract = async () => {
    if (!text) return;
    setLoading(true);

    const res = await fetch("http://127.0.0.1:8000/extract", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ job_description: text, cv: cvText }),
    });

    const data = await res.json();
    setResult(data);
    setLoading(false);
  };

  const hasCV = cvText.trim().length > 0;

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-950 to-slate-900 text-white">

      {/* NAVBAR */}
      <div className="flex justify-between items-center px-8 py-4 border-b border-slate-800">
        <div className="flex items-center gap-3">
          <div className="bg-white/5 p-1.5 rounded-md">
            <img src={logo} className="h-6" />
          </div>
          <span className="font-semibold text-lg">JobMatch</span>
        </div>

        <button
          onClick={() => window.open(PAYMENT_LINK)}
          className="bg-green-500 hover:bg-green-600 px-5 py-2 rounded-lg text-sm"
        >
          Upgrade — $3
        </button>
      </div>

      {/* HERO */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center mt-12 mb-8"
      >
        <h1 className="text-4xl font-bold mb-2">
          Understand Any Job Instantly
        </h1>
        <p className="text-gray-400">
          See required skills, your gaps, and how to improve
        </p>
      </motion.div>

      {/* MAIN */}
      <div className="max-w-5xl mx-auto px-6 grid md:grid-cols-2 gap-6">

        {/* INPUT */}
        <motion.div
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="bg-slate-900 p-6 rounded-xl border border-slate-800 space-y-4"
        >
          <textarea
            className="w-full h-36 p-4 rounded-lg bg-slate-950 border border-slate-700"
            placeholder="Paste job description..."
            value={text}
            onChange={(e) => setText(e.target.value)}
          />

          <textarea
            className="w-full h-24 p-4 rounded-lg bg-slate-950 border border-slate-700"
            placeholder="Paste your CV (optional)"
            value={cvText}
            onChange={(e) => setCvText(e.target.value)}
          />

          <button
            onClick={handleExtract}
            className="w-full py-3 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-lg font-semibold"
          >
            {loading ? "Analyzing..." : "Analyze Job Match"}
          </button>
        </motion.div>

        {/* RESULTS */}
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="bg-slate-900 p-6 rounded-xl border border-slate-800 space-y-6"
        >
          {!result && (
            <p className="text-gray-500 text-center">
              Results will appear here
            </p>
          )}

          {result && (
            <>
              <div className="bg-slate-950 p-4 rounded-lg">
                <p className="text-sm text-gray-400">Match Score</p>

                {!hasCV ? (
                  <p className="text-gray-500 mt-2">
                    Upload CV to unlock score
                  </p>
                ) : (
                  <>
                    <p className="text-4xl font-bold text-indigo-400">
                      {result.score}%
                    </p>
                    <p className="text-gray-400">
                      {result.explanation}
                    </p>
                  </>
                )}
              </div>

              <Section title="Core Skills" items={result.core_skills} />
              <Section title="All Skills" items={result.skills} />

              <div className="bg-slate-950 p-5 rounded-lg text-center">
                <p className="font-semibold mb-2">
                  🔒 Unlock Full Report — $3
                </p>

                <button
                  onClick={() => window.open(PAYMENT_LINK)}
                  className="bg-green-500 px-5 py-2 rounded-lg"
                >
                  Get Full Report
                </button>
              </div>
            </>
          )}
        </motion.div>
      </div>
    </div>
  );
}

function Section({ title, items = [] }) {
  return (
    <div>
      <h3 className="mb-2">{title}</h3>
      <div className="flex flex-wrap gap-2">
        {items.map((item, i) => (
          <span key={i} className="bg-slate-700 px-3 py-1 rounded text-sm">
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

export default App;
